// src/firebase.ts
function handleFirestoreError(error, operationType, path) {
  const errInfo = {
    error: error instanceof Error ? error.message : String(error),
    authInfo: {
      userId: auth2.currentUser?.uid,
      email: auth2.currentUser?.email,
      emailVerified: auth2.currentUser?.emailVerified,
      isAnonymous: auth2.currentUser?.isAnonymous,
      tenantId: auth2.currentUser?.tenantId,
      providerInfo: auth2.currentUser?.providerData?.map((provider) => ({
        providerId: provider.providerId,
        email: provider.email
      })) || []
    },
    operationType,
    path
  };
  console.error("Firestore Error: ", JSON.stringify(errInfo));
  throw new Error(JSON.stringify(errInfo));
}
async function testConnection() {
  try {
    await getDocsFromServer(query(collection(db, "songs"), where("status", "==", "published"), where("visibility", "==", "public"), limit(1)));
    return { ok: true, message: "Conectado ao Firebase com sucesso." };
  } catch (error) {
    if (error?.code === "permission-denied") {
      return { ok: false, message: "Sem permissão para consultar músicas públicas. Verifique as regras do Firestore." };
    }
    if (error?.code === "unavailable" || error?.message?.includes("client is offline")) {
      return { ok: false, message: "Firestore indisponível; modo local ativo." };
    }
    return { ok: false, message: "Falha ao conectar ao Firestore." };
  }
}
async function loginWithGoogle() {
  const result = await signInWithPopup(auth2, googleProvider);
  if (result.user) {
    await syncUserProfile(result.user);
  }
  return result.user;
}
async function signUpWithEmail(email, pass, name, instruments = ["Guitarra", "Vocal"]) {
  const cred = await createUserWithEmailAndPassword(auth2, email, pass);
  if (name && cred.user) {
    await updateProfile(cred.user, { displayName: name });
  }
  await syncUserProfile(cred.user, { displayName: name, instruments });
  return cred.user;
}
async function signInWithEmail(email, pass) {
  const cred = await signInWithEmailAndPassword(auth2, email, pass);
  await syncUserProfile(cred.user);
  return cred.user;
}
async function logoutUser() {
  await signOut(auth2);
}
async function sendPasswordReset(email) {
  await sendPasswordResetEmail(auth2, email);
}
async function syncUserProfile(user, additionalData = {}) {
  if (!user)
    return null;
  const userRef = doc(db, "users", user.uid);
  try {
    const snap = await getDoc(userRef);
    if (!snap.exists()) {
      const newProfile = {
        uid: user.uid,
        email: user.email || "",
        displayName: user.displayName || additionalData.displayName || "Músico Virtuoso",
        photoURL: user.photoURL || "",
        role: "musician",
        instruments: additionalData.instruments || ["Guitarra", "Vocal"],
        level: "intermediario",
        currentBand: "Solo / Convidado",
        reputationScore: 100,
        createdAt: serverTimestamp(),
        updatedAt: serverTimestamp(),
        ...additionalData
      };
      await setDoc(userRef, newProfile);
      return newProfile;
    }
    return snap.data();
  } catch (err) {
    console.warn("Erro ao sincronizar perfil do usuário:", err);
    return null;
  }
}
